/**
 * @brief Updates UI elements related to the loaded (or active) trajectory.
 */
void MainWindow::UpdateTrajectoryControls() {
    const QString n_poses = QString::number(trajectory_.size());
    if (trajectory_.empty()) {
        // Nothing recorded or loaded
        ui_->l_trajectory_name->setText("...");
        ui_->l_trajectory_step->setText("...");
    } else if (trajectory_file_.isEmpty()) {
        // Unsaved recording
        ui_->l_trajectory_name->setText("Recording");
        ui_->l_trajectory_step->setText(n_poses + "/-");  // total unknown
    } else {
        // From file
        ui_->l_trajectory_name->setText(
            QFileInfo(trajectory_file_).completeBaseName());
        ui_->l_trajectory_step->setText(
            "-/" + n_poses);  // step unknown (not started yet)
    }
    if (trajectory_step_) {
        // Regardless of state
        ui_->l_trajectory_step->setText(GetTrajectoryStepText());
    }

    // Clearly display which state is active
    if (trajectory_playing_) {
        ui_->pb_trajectory_play->setIcon(
            QIcon::fromTheme(QIcon::ThemeIcon::MediaPlaybackPause));
        ui_->pb_trajectory_play->setText(" PAUSE");
        ui_->pb_trajectory_play->setStyleSheet(
            QString("QPushButton:enabled {color: %1;}").arg(Color::kRed));
    } else {
        ui_->pb_trajectory_play->setIcon(
            QIcon::fromTheme(QIcon::ThemeIcon::MediaPlaybackStart));
        ui_->pb_trajectory_play->setText(" PLAY");
        ui_->pb_trajectory_play->setStyleSheet(
            QString("QPushButton:enabled {color: %1;}").arg(Color::kGreen));
    }

    ui_->pb_trajectory_clear->setEnabled(!trajectory_.empty()
                                         && !trajectory_playing_);
    ui_->a_trajectory_load->setEnabled(!trajectory_playing_);
    ui_->a_trajectory_save->setEnabled(!trajectory_.empty());

    UpdateActuatorControls();
}

/**
 * @brief Starts or stops trajectory playback, locking controls that would
 *        interfere while it plays.
 *
 * @param playing Whether the trajectory is playing
 */
void MainWindow::SetTrajectoryPlaying(const bool& playing) {
    trajectory_playing_ = playing;
    if (!playing) {
        step_delay_timer_->stop();
    }

    // UI widgets
    UpdateTrajectoryControls();
    UpdateModeControls();
}

/**
 * @brief Moves to the next trajectory step once arm has settled; wraps around
 *        if looping, otherwise finishes playback.
 *
 * @note Only used by `step_delay_timer_` (see signal/slot connection in
 *       `SetupUi()`); separate function for readability.
 */
void MainWindow::PlayNextTrajectoryStep() {
    // Calculate next step
    const bool reverse = ui_->pb_trajectory_reverse->isChecked();
    const std::size_t first = reverse ? trajectory_.size() - 1 : 0;
    const std::size_t last = reverse ? 0 : trajectory_.size() - 1;

    if (*trajectory_step_ == last && !ui_->chk_trajectory_loop->isChecked()) {
        logger_->Info("Trajectory complete");
        trajectory_step_.reset();
        SetTrajectoryPlaying(false);
        return;
    }

    if (*trajectory_step_ == last) {
        trajectory_step_ = first;  // loop
    } else {
        trajectory_step_ = reverse ? *trajectory_step_ - 1
                                   : *trajectory_step_ + 1;
    }

    // Ask for confirmation (if necessary) before proceeding
    if (ui_->chk_trajectory_confirm->isChecked() && !ConfirmTrajectoryStep()) {
        logger_->Info("Trajectory paused before step "
                      + GetTrajectoryStepText().toStdString());
        SetTrajectoryPlaying(false);
        return;
    }

    // Send next step to actuators and update UI
    logger_->Info("Trajectory step " + GetTrajectoryStepText().toStdString());
    SendJointTargets(trajectory_[*trajectory_step_]);

    UpdateTrajectoryControls();
}

/**
 * @brief Asks the user for confirmation before proceeding to the next
 *        trajectory step.
 *
 * @note "OK (don't ask again)" unchecks "Confirm steps".
 */
bool MainWindow::ConfirmTrajectoryStep() {
    const auto& pose = trajectory_[*trajectory_step_];

    QString text = "Move to step " + GetTrajectoryStepText() + "?\n";
    for (std::size_t i = 0; i < Motion::kNumJoints; ++i) {
        const auto joint = static_cast<Joint::Name>(i);
        text += "\n" + QString::fromStdString(Joint::NameEnumToString(joint))
                + ": " + QString::number(pose[i]) + " deg";
    }

    QMessageBox box(QMessageBox::Question, "Trajectory", text,
                    QMessageBox::Cancel, this);
    const auto* ok = box.addButton("OK", QMessageBox::AcceptRole);
    const auto* ok_always = box.addButton("OK (don't ask again)",
                                          QMessageBox::AcceptRole);
    box.setDefaultButton(QMessageBox::Cancel);
    box.exec();

    if (box.clickedButton() == ok_always) {
        ui_->chk_trajectory_confirm->setChecked(false);
        return true;
    }

    return box.clickedButton() == ok;
}

/**
 * @brief Gets the current trajectory step as "step/total" (1-based).
 */
QString MainWindow::GetTrajectoryStepText() const {
    return QString::number(*trajectory_step_ + 1) + "/"
           + QString::number(trajectory_.size());
}

