/**
 * @brief Adds the current target pose to the trajectory.
 *
 * @note A trajectory from file becomes an unsaved recording (i.e., no longer
 *       matches the file).
 */
void MainWindow::on_pb_trajectory_add_clicked() {
    trajectory_.push_back(current_target_);
    trajectory_file_.clear();
    logger_->Info("Added pose " + std::to_string(trajectory_.size())
                  + " to recording");

    UpdateTrajectoryControls();
}

/**
 * @brief Clears the trajectory (asks user for confirmation).
 */
void MainWindow::on_pb_trajectory_clear_clicked() {
    const QString question = trajectory_file_.isEmpty()
                                 ? "Clear unsaved recording (%1 poses)?"
                                 : "Clear loaded trajectory (%1 poses)?";
    const auto reply = QMessageBox::question(this, "Clear Trajectory",
                                             question.arg(trajectory_.size()),
                                             QMessageBox::Yes | QMessageBox::No,
                                             QMessageBox::No);
    if (reply != QMessageBox::Yes) {
        logger_->Debug("Trajectory clear cancelled by user");
        return;
    }

    logger_->Info("Cleared trajectory (" + std::to_string(trajectory_.size())
                  + " poses)");
    trajectory_.clear();
    trajectory_file_.clear();
    trajectory_step_.reset();

    UpdateTrajectoryControls();
}

/**
 * @brief Plays or pauses the trajectory, based on its current state.
 *
 * @note Pausing stops the arm like STOP, keeping the current step; playing
 *       again re-sends that step without asking (starting from the beginning
 *       always asks to confirm the first move).
 */
void MainWindow::on_pb_trajectory_play_clicked() {
    if (trajectory_playing_) {
        ui_->pb_arm_stop->click();  // also pauses playback
        return;
    }

    // Start at the first step in the playback direction
    if (!trajectory_step_) {
        trajectory_step_ = ui_->pb_trajectory_reverse->isChecked()
                               ? trajectory_.size() - 1
                               : 0;
        if (!ConfirmTrajectoryStep()) {
            logger_->Debug("Trajectory start cancelled by user");
            trajectory_step_.reset();
            return;
        }
    }

    logger_->Info("Playing trajectory from step "
                  + GetTrajectoryStepText().toStdString());
    SetTrajectoryPlaying(true);
    SendJointTargets(trajectory_[*trajectory_step_]);
}
